node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { defineIR, runDifferential } from './dist/framework/contracts/index.js';
import { defineAdapter, createIRArtifact } from './dist/framework/ir/index.js';
import { applyPass, definePass } from './dist/framework/passes/index.js';
import { AnalysisManager } from './dist/framework/contracts/index.js';
const validate = v => assert.ok(Array.isArray(v.values));
const ir = defineIR({id:'probe.tensor',version:'1',description:'probe',validate});
const part = v => ({id:'body',kind:'statement',attributes:v});
const adapter = defineAdapter({id:ir.id,version:'1',kind:ir.id,schemaVersion:ir.version,description:'probe',relationKinds:{},validate,entities:v=>[part(v)],resolve:(v,id)=>id==='body'?part(v):undefined,relations:()=>[],describe:(_v,e)=>({label:e.id})});
const values = [1,0,0,0,2**-24,2**-24];
const original = createIRArtifact(adapter,'probe',{values,block:0});
const rewrite = definePass({id:'probe.block',version:'1',description:'probe',ir,adapter,writes:{entities:['statement'],relations:[]},run:({before})=>({native:{...before.value,block:4}})});
const result = applyPass(rewrite,original,{manager:new AnalysisManager()});
assert.ok(result instanceof Promise);
const {artifact:candidate,changes} = await result;
assert.equal(changes.entities.length,1);
const run = (v,f) => { const fold = xs=>xs.reduce((s,x)=>f(s+x),0); return v.block ? fold([fold(v.values.slice(0,4)),fold(v.values.slice(4))]) : fold(v.values); };
const check = tolerance => runDifferential({id:tolerance?'probe.tolerance':'probe.exact',version:'1',description:'probe',inputs:{baseline:ir,subject:ir},baseline:'baseline',subject:'subject',count:1,cases:()=>[0],run:(side,a)=>run(a.value,tolerance&&side==='baseline'?x=>x:Math.fround),compare:(a,b)=>tolerance?Math.abs(a-b)<=1e-5+1e-5*Math.abs(a):Object.is(a,b)},{baseline:original,subject:candidate});
assert.equal(check(false).status,'disagree');
assert.equal(check(true).status,'agree');
console.log('applyPass returned a Promise; the native result produced one entity diff; runDifferential synchronously returned disagree (exact) and agree (tolerance).');
